import * as THREE from 'three';
import {createBattle,createTournament,PROFILES,WEAPONS,DEFENSE,SHIELD,ZONES,isCinematicMissile} from './battle-engine.js';
import {createZoneVisuals} from './zone-visuals.js';
import {createOrbitalVisuals} from './orbital-visuals.js';
import {territoryTargets} from './territory.js';

export function createArena({countries,features,scene,camera,controls,spherical,glowTexture,paint,focus}) {
 const $=id=>document.getElementById(id),palette=[0x77e5da,0xff916b,0xbca0ff,0xf3d975,0x6dadff,0xf88cb7];
 const defaults=['FRA','BRA','USA','CHN','ZAF','AUS'];
 let roster=defaults.map((id,i)=>({...countries.find(c=>c.id===id),profile:['aggressive','defensive','opportunist'][i%3]})),teams=roster.slice(0,2),colors=palette.slice(0,2),slot=0,speed=1,following=true,cinematic=null,tournament=null,nextRound=null,uiTime=0,renderedCount=0;
 let totals=new Map(),elapsed=0,highlight=null,shake=0,shakeTime=0;
 const targetCache=new Map(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function withTargets(player){if(!targetCache.has(player.id)){const feature=features.find(f=>f.id===player.id);targetCache.set(player.id,feature?territoryTargets(feature):[{lat:player.lat,lon:player.lon}]);}return {...player,targets:targetCache.get(player.id),doctrine:$('salvo-priority').checked?'salvo':'balanced'};}
 const engine=createBattle(),visuals=new Map(),bursts=[],defenses=[],layer=new THREE.Group(),texture=glowTexture();scene.add(layer);
 const orbitalVisuals=createOrbitalVisuals({scene,features,spherical,glowTexture});
 const zoneVisuals=createZoneVisuals({scene,camera,spherical});
 const clock=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
 const busy=()=>['running','paused'].includes(engine.state.status)||nextRound!==null;
 const mode=()=>$('game-mode').value;
 const count=()=>mode()==='duel'?2:mode()==='tournament'?4:Number($('nation-count').value);
 const cssColor=n=>'#'+n.toString(16).padStart(6,'0');
 function log(message,type=''){const li=document.createElement('li');li.className=type;const time=document.createElement('time'),span=document.createElement('span');time.textContent=clock(engine.state.time);span.textContent=message;li.append(time,span);$('event-list').prepend(li);while($('event-list').children.length>55)$('event-list').lastChild.remove();}
 function dispose(obj){layer.remove(obj);obj.traverse(o=>{o.geometry?.dispose();if(o.material)for(const m of [o.material].flat())m.dispose();});}
 function clear(){for(const v of visuals.values())dispose(v.group);visuals.clear();for(const b of bursts)dispose(b.group);bursts.length=0;for(const d of defenses)dispose(d.group);defenses.length=0;shake=0;hostShake();stopCinema();}
 function hostShake(){const canvas=document.querySelector('#globe canvas');if(!canvas)return;canvas.style.transform=shake&&!reduced?`translate(${Math.sin(shakeTime*83)*shake}px,${Math.cos(shakeTime*97)*shake*.65}px)`:'none';}
 function frameTeams(){controls.target.set(0,0,0);const center=new THREE.Vector3();teams.forEach(t=>center.add(spherical(t.lat,t.lon,1)));if(center.length()<.1)center.copy(spherical(30,10,1));focus(center.normalize().multiplyScalar($('orbital-enabled').checked?8.8:teams.length>2?8.5:7.4));controls.autoRotate=false;}
 function paintTeams(){paint(teams,colors);}
 function renderSetup(){
  const n=count();$('nation-count').disabled=busy()||['duel','tournament'].includes(mode());$('nation-count').value=n;for(const option of $('nation-count').options)option.disabled=mode()==='ffa'?Number(option.value)<3:mode()==='teams'?![4,6].includes(Number(option.value)):false;
  const holder=$('nation-setup');holder.replaceChildren();
  for(let i=0;i<n;i++){
   const block=document.createElement('div');block.className='nation-config';block.style.setProperty('--team',cssColor(palette[i]));
   const button=document.createElement('button');button.className='slot-label'+(slot===i?' active':'');button.textContent=`${String.fromCharCode(65+i)} · ${mode()==='teams'?'ÉQUIPE '+(i%2+1):'NATION'}`;button.disabled=busy();button.setAttribute('aria-pressed',i===slot);button.onclick=()=>{slot=i;renderSetup();};
   const select=document.createElement('select');select.id=`choose-${i}`;select.setAttribute('aria-label',`Nation ${i+1}`);select.disabled=busy();countries.slice().sort((a,b)=>a.name.localeCompare(b.name,'fr')).forEach(c=>select.add(new Option(c.name,c.id)));select.value=roster[i].id;select.onchange=()=>{slot=i;choose(countries.find(c=>c.id===select.value));frameTeams();};
   const profile=document.createElement('select');profile.id=`profile-${i}`;profile.className='profile-select';profile.setAttribute('aria-label',`Stratégie de la nation ${i+1}`);profile.disabled=busy();Object.entries(PROFILES).forEach(([key,p])=>profile.add(new Option('IA '+p.name,key)));profile.value=roster[i].profile;profile.onchange=()=>{roster[i].profile=profile.value;prepare();};
   block.append(button,select,profile);holder.append(block);
  }
  $('game-mode').disabled=busy();$('salvo-priority').disabled=busy();$('orbital-enabled').disabled=busy();
 }
 function renderCards(){
  const sb=document.querySelector('.scoreboard');sb.replaceChildren();sb.dataset.count=teams.length;renderedCount=teams.length;
  teams.forEach((t,i)=>{const card=document.createElement('section');card.className='fighter';card.id=`fighter-${i}`;card.style.setProperty('--team',cssColor(colors[i]));card.innerHTML=`<div><span class="team-tag">IA ${String.fromCharCode(65+i)}</span><h2></h2><strong><span id="hp-${i}">100</span><small> PV</small></strong></div><div id="health-${i}" class="health" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="100"><i id="bar-${i}"></i></div><div class="energy-line"><span>ÉNERGIE <b id="energy-${i}">65</b></span><span>BOUCLIER <b id="shield-${i}">0</b></span></div><div class="energy-meter"><i id="energy-bar-${i}"></i></div><div id="shield-health-${i}" class="shield-meter" role="progressbar" aria-label="Bouclier territorial" aria-valuemin="0" aria-valuemax="40" aria-valuenow="40"><i id="shield-bar-${i}"></i></div><div class="orbital-status" id="orbital-${i}"></div><div class="ai-strategy" id="strategy-${i}"></div><div class="zone-status" id="zones-${i}"></div><div class="counter-status" id="counter-${i}"></div><div class="defense-stock" id="defense-${i}"></div><small id="stats-${i}"></small>`;card.querySelector('h2').textContent=t.name;card.querySelector('.health').setAttribute('aria-label',`Vie de ${t.name}`);sb.append(card);});
 }
 function updateUI(){
  const s=engine.state;if(renderedCount!==teams.length)renderCards();
  s.fighters.forEach((f,i)=>{if(!$(`hp-${i}`))return;$(`hp-${i}`).textContent=Math.ceil(f.hp);$(`bar-${i}`).style.width=f.hp+'%';$(`health-${i}`).setAttribute('aria-valuenow',Math.ceil(f.hp));$(`energy-${i}`).textContent=Math.floor(f.energy);$(`shield-${i}`).textContent=Math.ceil(f.shield)+'/40';$(`shield-bar-${i}`).style.width=(f.shield/SHIELD.capacity*100)+'%';$(`shield-health-${i}`).setAttribute('aria-valuenow',Math.ceil(f.shield));const satellite=s.satellites[i];const wait=Math.max(0,Math.ceil(f.shieldHitAt+SHIELD.rechargeDelay-s.time));$(`orbital-${i}`).textContent=(s.orbitalEnabled?(satellite.phase==='firing'?(satellite.decoy?'LASER LEURRÉ · ':'LASER ROUGE · ')+Math.max(0,5-satellite.elapsed).toFixed(1)+' s':satellite.phase==='transit'?'SATELLITE → '+teams[satellite.target]?.name:satellite.phase==='charging'?(s.fighters[satellite.target]?.jamUntil>s.time?'SATELLITE · verrouillage brouillé':'SATELLITE · charge '+Math.floor(f.energy)+'/40'):satellite.phase==='return'?'SATELLITE · orbite de retour':f.hp<=0?'SATELLITE · hors ligne':'SATELLITE · prêt'):'SATELLITE · désactivé')+(f.shield<SHIELD.capacity?(wait?' · bouclier +'+wait+' s':' · bouclier en recharge'):'');$(`orbital-${i}`).classList.toggle('firing',satellite.phase==='firing');$(`energy-bar-${i}`).style.width=f.energy+'%';$(`strategy-${i}`).textContent=`${PROFILES[f.profile].name} · ${f.hp<=0?'Éliminée':f.strategy}`;$(`defense-${i}`).textContent=`INTERCEPTEURS ${f.interceptors}/${DEFENSE.capacity}${f.reloadAt!==null?" · +1 dans "+Math.max(0,Math.ceil(f.reloadAt-s.time))+" s":" · stock plein"}${f.defenseReady>s.time?" · radar en recharge":""}`;$(`zones-${i}`).textContent=f.zones.map(z=>(z.type==='reactor'?'ϟ':z.type==='radar'?'◎':'▲')+' '+(z.hp>0?Math.ceil(z.hp):'HS')).join(' · ');$(`counter-${i}`).textContent=(f.jamUntil>s.time?'BROUILLAGE '+Math.ceil(f.jamUntil-s.time)+' s':f.jamReady>s.time?'Brouilleur '+Math.ceil(f.jamReady-s.time)+' s':'Brouilleur prêt')+' · '+(f.decoyUntil>s.time?'LEURRE '+Math.ceil(f.decoyUntil-s.time)+' s':f.decoyReady>s.time?'Leurre '+Math.ceil(f.decoyReady-s.time)+' s':'Leurre prêt');$(`stats-${i}`).textContent=`${f.shots} tirs · ${f.hits} impacts · ${f.blocked} interceptions`;$(`fighter-${i}`).classList.toggle('eliminated',f.hp<=0);});
  $('battle-time').textContent=clock(s.time);$('battle-status').textContent=nextRound!==null?'PROCHAINE MANCHE…':({idle:'PRÊT À LANCER',running:s.overtime?'MORT SUBITE · DÉGÂTS CROISSANTS':'AFFRONTEMENT EN COURS',paused:'SIMULATION EN PAUSE',finished:'PARTIE TERMINÉE'})[s.status];
  $('pause-battle').disabled=!['running','paused'].includes(s.status);$('pause-battle').textContent=s.status==='paused'?'Reprendre':'Pause';$('start-battle').textContent=busy()?'Affrontement en cours…':mode()==='tournament'?'Lancer le tournoi ↗':'Lancer l’affrontement ↗';$('start-battle').disabled=busy();document.body.dataset.battle=s.status;
  const pacts=s.alliances.filter(p=>p.until>s.time);$('diplomacy').textContent=pacts.length?pacts.map(p=>p.members.map(i=>teams[i].name).join(' ↔ ')+` · ${Math.ceil(p.until-s.time)} s`).join(' / '):s.mode==='teams'?'Équipes fixes · aucun tir allié':s.mode==='ffa'?'Diplomatie active · trêves temporaires':'Duel · aucune alliance';
 }
 function prepare(){if(busy())return;teams=roster.slice(0,count()).map((p,i)=>({...p,squad:i%2}));colors=teams.map((_,i)=>mode()==='teams'?palette[i%2]:palette[i]);engine.reset({satellites:$('orbital-enabled').checked,players:teams.map(withTargets),mode:mode()==='tournament'?'duel':mode()});renderCards();paintTeams();orbitalVisuals.update(engine.state,teams,colors);updateUI();}
 function choose(c){if(!countries.includes(c)||busy())return;slot=Math.min(slot,count()-1);const other=roster.findIndex(p=>p.id===c.id);if(other>=0&&other!==slot){const oldCountry=countries.find(x=>x.id===roster[slot].id);roster[other]={...oldCountry,profile:roster[other].profile};}roster[slot]={...c,profile:roster[slot].profile};prepare();renderSetup();}
 $('game-mode').onchange=()=>{if(mode()==='ffa'&&Number($('nation-count').value)<3)$('nation-count').value=4;if(mode()==='teams'&&![4,6].includes(Number($('nation-count').value)))$('nation-count').value=4;slot=0;tournament=null;nextRound=null;$('bracket').hidden=true;$('result').hidden=true;prepare();renderSetup();};
 $('nation-count').onchange=()=>{if(mode()==='teams'&&![4,6].includes(Number($('nation-count').value)))$('nation-count').value=4;if(mode()==='ffa'&&Number($('nation-count').value)<3)$('nation-count').value=3;slot=0;prepare();renderSetup();};
 function bracket(){const el=$('bracket');el.hidden=!tournament;if(!tournament)return;el.replaceChildren();tournament.matches.forEach((m,i)=>{const line=document.createElement('div');line.className=i===tournament.index?'current':'';line.textContent=`${m.label} · ${m.players.map(p=>p.name).join(' / ')}${m.winner?' → '+m.winner.name:''}`;el.append(line);});if(tournament.matches.length<3){const line=document.createElement('div');line.textContent='Finale · en attente des vainqueurs';el.append(line);}}
 function beginMatch(players){clear();teams=players;colors=players.map((_,i)=>engine.state.mode==='teams'?palette[i%2]:palette[i]);engine.start({satellites:$('orbital-enabled').checked,players:players.map(withTargets),mode:mode()==='tournament'?'duel':mode()});colors=players.map((_,i)=>engine.state.mode==='teams'?palette[i%2]:palette[i]);$('result').hidden=true;renderCards();following=$('follow-battle').checked;frameTeams();paintTeams();log(tournament?tournament.current.label+' · '+teams.map(t=>t.name).join(' contre '):teams.map(t=>t.name).join(' · ')+' : début de l’affrontement.');renderSetup();bracket();updateUI();}
 function start(){nextRound=null;tournament=mode()==='tournament'?createTournament(roster.slice(0,4)):null;totals=new Map();elapsed=0;highlight=null;$('event-list').replaceChildren();beginMatch(tournament?tournament.current.players:roster.slice(0,count()).map((p,i)=>({...p,squad:i%2})));if(innerWidth<=700)document.querySelector('.world').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
 $('start-battle').onclick=start;$('replay-battle').onclick=()=>{if(nextRound!==null){nextRound=0;return;}start();};
 $('salvo-priority').onchange=prepare;$('orbital-enabled').onchange=prepare;
 $('pause-battle').onclick=()=>{engine.pause();updateUI();};
 $('reset-battle').onclick=()=>{nextRound=null;tournament=null;clear();engine.reset();$('result').hidden=true;$('bracket').hidden=true;$('event-list').replaceChildren();prepare();renderSetup();log('Choisissez le mode, les nations et leurs profils IA.');};
 $('speed-battle').onchange=e=>{speed=Number(e.target.value);};$('follow-battle').onchange=e=>{following=e.target.checked;stopCinema();if(following)frameTeams();};$('cinematic-battle').checked=!matchMedia('(prefers-reduced-motion: reduce)').matches;$('cinematic-battle').onchange=()=>{if(!$('cinematic-battle').checked)stopCinema();};
 controls.addEventListener('start',()=>{following=false;$('follow-battle').checked=false;stopCinema(false);});
 function stopCinema(returnToWorld=true){if(!cinematic)return;cinematic=null;$('cinematic-label').hidden=true;focus(null);if(returnToWorld)frameTeams();}
 function route(f){
  const source=f.sourcePoint||teams[f.from],target=f.targetPoint||teams[f.to];
  const a=spherical(source.lat,source.lon,1),b=spherical(target.lat,target.lon,1),angle=Math.acos(THREE.MathUtils.clamp(a.dot(b),-1,1));
  let tangent=b.clone().addScaledVector(a,-a.dot(b));if(tangent.length()<.0001){tangent.crossVectors(a,new THREE.Vector3(0,1,0));if(tangent.length()<.001)tangent.crossVectors(a,new THREE.Vector3(1,0,0));}tangent.normalize();
  const side=new THREE.Vector3().crossVectors(a,tangent).normalize();
  return t=>a.clone().multiplyScalar(Math.cos(angle*t)).addScaledVector(tangent,Math.sin(angle*t)).addScaledVector(side,(f.bend||0)*Math.sin(Math.PI*t)).normalize().multiplyScalar(2.04+Math.sin(Math.PI*t)*(.35+angle*.35+(f.loft||0)));
 }
 function launch(f){const group=new THREE.Group(),path=route(f),color=colors[f.from],heavy=f.kind==='heavy',size=heavy?1.8:f.kind==='salvo'?.65:1;const body=new THREE.Mesh(new THREE.ConeGeometry(.027*size,.13*size,8),new THREE.MeshBasicMaterial({color:heavy?0xffe8b0:0xffffff})),glow=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color,blending:THREE.AdditiveBlending,depthWrite:false}));glow.scale.setScalar(.22*size);group.add(body,glow);const tail=new THREE.Line(new THREE.BufferGeometry().setFromPoints(Array.from({length:40},()=>path(0))),new THREE.LineBasicMaterial({color,transparent:true,opacity:.9}));group.add(tail);layer.add(group);visuals.set(f.id,{group,body,glow,tail,path,flight:f});
  if(isCinematicMissile(f)&&following&&$('cinematic-battle').checked&&!cinematic){focus(null);controls.autoRotate=false;cinematic={id:f.id,linger:0};$('cinematic-label').hidden=false;$('cinematic-label').textContent=`CAMÉRA TITAN · ${teams[f.from].name} → ${teams[f.to].name} · ${f.damage} dégâts`;$('cinematic-label').dataset.kind=f.kind;}
  if(f.kind!=='salvo'||f.index%5===0)log(`${teams[f.from].name} → ${teams[f.to].name} · ${WEAPONS[f.kind].name} ${f.kind==='salvo'?'groupe '+(f.group+1)+'/4 · 5 missiles':f.damage+' dégâts'}`,f.from===0?'team-a':'team-b');}

 function burst(position,color,scale=1){const group=new THREE.Group();group.position.copy(position);const ball=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color,blending:THREE.AdditiveBlending,depthWrite:false})),ring=new THREE.Mesh(new THREE.RingGeometry(.85,1,48),new THREE.MeshBasicMaterial({color,transparent:true,side:THREE.DoubleSide,depthWrite:false}));ring.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),position.clone().normalize());group.add(ball,ring);const particleGeometry=new THREE.BufferGeometry(),velocities=new Float32Array(48);for(let i=0;i<16;i++){const velocity=new THREE.Vector3().randomDirection().multiplyScalar(.2+Math.random()*.4);velocities.set(velocity.toArray(),i*3);}particleGeometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(48),3));const sparks=new THREE.Points(particleGeometry,new THREE.PointsMaterial({color,size:.025,transparent:true,depthWrite:false}));sparks.userData.velocities=velocities;group.add(sparks);layer.add(group);bursts.push({group,ball,ring,sparks,age:0,duration:1.5,scale});}
 function shieldEffect(index,repair=false){const group=new THREE.Group();group.position.copy(spherical(teams[index].lat,teams[index].lon,2.03));const shield=new THREE.Mesh(new THREE.SphereGeometry(.15,20,12),new THREE.MeshBasicMaterial({color:repair?0xa3ffaf:colors[index],transparent:true,opacity:.5,wireframe:true}));group.add(shield);layer.add(group);defenses.push({group,mesh:shield,age:0,duration:repair?1.5:3,kind:'shield'});}
 function interceptor(f){const v=visuals.get(f.id);if(!v)return;const end=v.path(.9),start=spherical(teams[f.to].lat,teams[f.to].lon,2.06),group=new THREE.Group(),ball=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color:0xc6eeff,blending:THREE.AdditiveBlending,depthWrite:false}));ball.scale.setScalar(.13);const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([start,start]),new THREE.LineBasicMaterial({color:0xbde6ff}));group.add(ball,line);layer.add(group);defenses.push({group,ball,line,start,end,age:0,duration:Math.max(.1,f.duration*(.9-f.defenseAt)),kind:'interceptor',success:f.intercepted});shieldEffect(f.to);}
 function removeFlight(f){const v=visuals.get(f.id);if(v){dispose(v.group);visuals.delete(f.id);}if(cinematic?.id===f.id)cinematic.linger=.9;}
 function result(){
  const s=engine.state;elapsed+=s.time;if(s.decisive&&(!highlight||s.decisive.damage>highlight.damage))highlight={...s.decisive,source:teams[s.decisive.from].name,target:teams[s.decisive.to].name,round:tournament?.current.label};for(const v of visuals.values())dispose(v.group);visuals.clear();stopCinema();
  s.fighters.forEach((f,i)=>{const key=teams[i].id,old=totals.get(key)||{...f,name:teams[i].name,shots:0,hits:0,blocked:0,damage:0,repaired:0,laserDamage:0,bestStreak:0,wins:0};['shots','hits','blocked','damage','repaired','laserDamage'].forEach(k=>old[k]+=f[k]);old.bestStreak=Math.max(old.bestStreak,f.bestStreak);old.wins+=s.winners.includes(i)?1:0;totals.set(key,old);});
  let heading=s.winners.length?(s.mode==='teams'?`Équipe ${s.fighters[s.winner].squad+1} victorieuse`:teams[s.winner].name+' remporte la partie'):'Égalité !';
  if(tournament){const winner=s.winner===null?s.fighters.map((f,i)=>({i,damage:f.damage})).sort((a,b)=>b.damage-a.damage)[0].i:s.winner;if(s.winner===null)log('Égalité départagée aux dégâts infligés pour le tournoi.');const next=tournament.record(teams[winner]);if(next){heading=teams[winner].name+' gagne la manche';nextRound=5;$('replay-battle').textContent='Passer à la manche suivante ↗';}else{heading=tournament.champion.name+' remporte le tournoi';$('replay-battle').textContent='Rejouer le tournoi ↗';}bracket();}
  else $('replay-battle').textContent='Rejouer cet affrontement ↗';
  $('result').hidden=false;$('result-title').textContent=heading;$('result-detail').textContent=`${clock(elapsed)} ${tournament?'cumulées':''} · ${[...totals.values()].reduce((a,f)=>a+f.shots,0)} missiles · ${[...totals.values()].reduce((a,f)=>a+f.blocked,0)} interceptions`;
  const table=$('result-stats');table.replaceChildren();const caption=document.createElement('caption');caption.textContent=tournament?'Bilan cumulé du tournoi':'Bilan de la partie';const head=document.createElement('thead');head.innerHTML='<tr><th>Nation</th><th>Dégâts</th><th>Laser</th><th>Impacts</th><th>Interc.</th><th>Série</th><th>Répar.</th></tr>';const body=document.createElement('tbody');for(const f of [...totals.values()].sort((a,b)=>b.damage-a.damage)){const tr=document.createElement('tr');[f.name,Math.round(f.damage),Math.round(f.laserDamage),Math.round(f.hits/Math.max(1,f.shots)*100)+' %',f.blocked,f.bestStreak,f.repaired].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td);});body.append(tr);}table.append(caption,head,body);
  const d=highlight;$('decisive').textContent=d?`Frappe la plus forte : ${d.source} → ${d.target}, ${Math.round(d.damage*10)/10} PV à ${clock(d.time)} (${(WEAPONS[d.kind]?.name||'Laser orbital')}${d.round?' · '+d.round:''}).`:'';log(heading,'victory');renderSetup();updateUI();
 }
 function tick(dt){
  const delta=dt*speed,wasRunning=engine.state.status==='running';if(nextRound!==null){nextRound-=delta;$('next-round').textContent=`Prochaine manche dans ${Math.max(0,Math.ceil(nextRound))} s`;if(nextRound<=0){nextRound=null;$('next-round').textContent='';beginMatch(tournament.current.players);}}else $('next-round').textContent='';
  const events=engine.step(delta);for(const event of events){const f=event.flight;
   if(event.type==='launch')launch(f);
   if(event.type==='defend'){interceptor(f);log(teams[f.to].name+' lance un intercepteur.','intercept');}
   if(['impact','intercept','cancel'].includes(event.type)){const v=visuals.get(f.id);if(event.type!=='cancel'){const intercepted=event.type==='intercept',p=v?v.path(intercepted?.9:1):spherical(teams[f.to].lat,teams[f.to].lon,2.06);burst(p,intercepted?0xb7e5ff:colors[f.from],f.kind==='heavy'?1.5:.8);log(intercepted?teams[f.to].name+' intercepte '+WEAPONS[f.kind].name:`${teams[f.to].name} · −${Math.round(event.damage*10)/10} PV${event.absorbed?' · bouclier absorbe '+Math.round(event.absorbed*10)/10:''}`,intercepted?'intercept':'impact');if(!intercepted&&event.damage>0&&!reduced)shake=Math.min(4.5,Math.max(shake,f.kind==='heavy'?3.5:1.3));}removeFlight(f);}
   if(event.type==='laserStart')log(teams[event.from].name+' active son laser orbital sur '+teams[event.to].name+(event.decoy?' · leurre détecté, aucun dégât.':' · 5 secondes.'),'laser');
   if(event.type==='jam')log(teams[event.from].name+' brouille le verrouillage orbital pendant 7 s (22 énergie).','intercept');
   if(event.type==='decoy')log(teams[event.from].name+' déploie un leurre orbital pendant 9 s (18 énergie).','intercept');
   if(event.type==='zoneDestroyed')log(teams[event.from].name+' : '+ZONES[event.zone].name+' neutralisée.','impact');
   if(event.type==='laserEnd')log('Fin du laser orbital de '+teams[event.from].name+'.','laser');
   if(event.type==='shield'){shieldEffect(event.from);log(teams[event.from].name+' recharge son bouclier territorial.','intercept');}
   if(event.type==='repair'){shieldEffect(event.from,true);log(teams[event.from].name+` se répare (+${event.amount} PV).`,'repair');}
   if(event.type==='lastStand'){shieldEffect(event.from);log(teams[event.from].name+' tente sa dernière offensive !','impact');}
   if(event.type==='alliance')log(event.members.map(i=>teams[i].name).join(' ↔ ')+' : trêve de 12 secondes.','victory');
   if(event.type==='allianceEnd')log('Fin de la trêve : '+event.members.map(i=>teams[i].name).join(' / '));
   if(event.type==='betrayal')log(teams[event.from].name+' rompt la trêve avec '+teams[event.to].name+' !','impact');
   if(event.type==='eliminated')log(teams[event.from].name+' est éliminée.','impact');
   if(event.type==='overtime')log('Mort subite : réparations suspendues, énergie et dégâts augmentés.','victory');
   if(event.type==='finish')result();
  }
  if(wasRunning)for(const v of visuals.values()){const f=v.flight,t=THREE.MathUtils.clamp((engine.state.time-f.start)/f.duration,0,1),p=v.path(t);v.body.position.copy(p);v.glow.position.copy(p);const tangent=v.path(Math.min(1,t+.002)).sub(v.path(Math.max(0,t-.002))).normalize();v.body.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),tangent);const attr=v.tail.geometry.attributes.position;for(let i=0;i<40;i++){const point=v.path(Math.max(0,t-(39-i)*.004));attr.setXYZ(i,...point.toArray());}attr.needsUpdate=true;v.tail.geometry.computeBoundingSphere();}
  if(engine.state.status!=='paused'){
   for(let i=bursts.length-1;i>=0;i--){const b=bursts[i];b.age+=delta;const p=b.age/b.duration;b.ball.scale.setScalar((.1+Math.sin(Math.min(1,p)*Math.PI)*.9)*b.scale);b.ball.material.opacity=Math.max(0,1-p);b.ring.scale.setScalar((.04+p*.5)*b.scale);b.ring.material.opacity=Math.max(0,(1-p)*.9);const particles=b.sparks.geometry.attributes.position,velocities=b.sparks.userData.velocities;for(let i=0;i<16;i++)particles.setXYZ(i,velocities[i*3]*b.age,velocities[i*3+1]*b.age,velocities[i*3+2]*b.age);particles.needsUpdate=true;b.sparks.geometry.computeBoundingSphere();b.sparks.material.opacity=Math.max(0,1-p);if(p>=1){dispose(b.group);bursts.splice(i,1);}}
   for(let i=defenses.length-1;i>=0;i--){const d=defenses[i];d.age+=delta;const p=Math.min(1,d.age/d.duration);if(d.kind==='shield'){d.mesh.scale.setScalar(1+p*2);d.mesh.material.opacity=(1-p)*.6;}else{const point=d.start.clone().lerp(d.end,p);d.ball.position.copy(point);const attr=d.line.geometry.attributes.position;attr.setXYZ(0,...d.start.clone().lerp(d.end,Math.max(0,p-.2)).toArray());attr.setXYZ(1,...point.toArray());attr.needsUpdate=true;d.line.geometry.computeBoundingSphere();}if(p>=1){if(d.kind==='interceptor'&&!d.success)burst(d.end,0x8cb8d8,.22);dispose(d.group);defenses.splice(i,1);}}
   if(cinematic){const v=visuals.get(cinematic.id);if(v){const p=v.body.position,desired=p.clone().normalize().multiplyScalar(6.2);camera.position.lerp(desired,1-Math.exp(-dt*3));controls.target.lerp(p.clone().multiplyScalar(.65),1-Math.exp(-dt*3));}else{cinematic.linger-=dt;if(cinematic.linger<=0)stopCinema();}}
  }
  if(engine.state.status==='paused'){const canvas=document.querySelector('#globe canvas');if(canvas)canvas.style.transform='none';}else{shakeTime+=dt;shake*=Math.exp(-dt*9);if(shake<.05)shake=0;hostShake();}
  orbitalVisuals.update(engine.state,teams,colors);zoneVisuals.update(engine.state,teams,colors);
  uiTime+=dt;if(uiTime>.12||events.length){updateUI();uiTime=0;}
 }
 prepare();renderSetup();log('Choisissez un mode, les nations et leurs profils IA.');
 return {tick,choose,repaint:paintTeams};
}
